# Create a neighborhood matrix
neighborhood_matrix = {}
for index, row in adjacency_df.iterrows():
    if row['borough'] not in neighborhood_matrix:
        neighborhood_matrix[row['borough']] = []
    if row['neighbor'] not in neighborhood_matrix:
        neighborhood_matrix[row['neighbor']] = []
    neighborhood_matrix[row['borough']].append(row['neighbor'])
    neighborhood_matrix[row['neighbor']].append(row['borough'])

# Define a function to calculate the Getis-Ord Gi* statistic
def getis_ord_gi(borough, neighborhood_matrix, df):
    if borough not in neighborhood_matrix:
        return 0
    neighborhood = neighborhood_matrix[borough]
    values = [df.loc[neighbor]['GHG_value'] for neighbor in neighborhood if neighbor in df.index]
    if len(values) == 0:
        return 0
    mean_value = np.mean(values)
    std_dev = np.std(values)
    if std_dev == 0:
        return 0
    else:
        return (mean_value - df.loc[borough]['GHG_value']) / std_dev

# Calculate the Getis-Ord Gi* statistic for each borough
gi_values = {}
for borough in df['borough'].unique():
    gi_values[borough] = getis_ord_gi(borough, neighborhood_matrix, df)

# Print the results
for borough, gi_value in gi_values.items():
    if np.abs(gi_value) > 1.96:  # 95% confidence
        print(f'{borough} (HOT, z-score = {gi_value})')

# Filter the results to exclude boroughs with missing values
filtered_results = {borough: gi_value for borough, gi_value in gi_values.items() if not pd.isnull(df.loc[borough]['GHG_value'])}
